import React from 'react';
import './Footer.css';

function Footer() {
    return (
      <footer className="footer-container">
        <div className="footer-info">
          <h3>About Saree Boutique</h3>
          <p>
            At Saree Boutique, we bring you the finest collection of sarees and exquisite jewelry that reflect timeless beauty 
            and cultural elegance. Our carefully curated sarees are crafted from premium fabrics, embracing both traditional 
            and contemporary designs. 
          </p>
        </div>
        <div className="footer-contact">
          <h3>Contact Us</h3>
          <p>Email: <a href="mailto:saree-boutique@shop.com">saree-boutique@shop.com</a></p>
          <p>Phone: <a href="tel:123-456-7890">123-456-7890</a></p>
        </div>
        <div>
        <i class="bi bi-instagram"></i>
        </div>
      </footer>
    );
  }
  
  export default Footer;
